from itertools import combinations, product
import heapq


def _build_interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"], row["id"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (ids < best_ids if tie == "smallest" else ids > best_ids))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        domains = [[None] + [row["version"] for row in packages[name]] for name in names]
        best_score = None
        best_versions = None

        for values in product(*domains):
            chosen = {name: version for name, version in zip(names, values)
                      if version is not None}
            if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue
            if any(name in chosen and chosen[name] != version
                   for name, version in data.get("pins", {}).items()):
                continue
            if any(name in chosen and chosen[name] in data.get("blocked", {}).get(name, [])
                   for name in names):
                continue

            graph = {}
            valid = True
            for name, version in chosen.items():
                row = next(row for row in packages[name] if row["version"] == version)
                edges = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = chosen.get(target)
                    if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    edges.append(target)
                graph[name] = edges
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if name not in chosen:
                    valid = False
                    break
                reachable.add(name)
                stack.extend(graph.get(name, []))
            if not valid or reachable != set(chosen):
                continue

            done, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for target in graph.get(name, []):
                    if not visit(target):
                        return False
                active.remove(name)
                done.add(name)
                return True
            if any(not visit(name) for name in chosen):
                continue

            score = tuple(chosen.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = chosen
        if best_score is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        node_masks = [0] * data["n"]
        for i, node in enumerate(required):
            node_masks[node] |= 1 << i
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial = (source, node_masks[source], 0)
        best = {initial: data["start"]}
        queue = [(data["start"], source, node_masks[source], 0)]
        coupons = data["coupons"]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if node == data["target"] and mask == full_mask and used == coupons:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], used)]
                if used < coupons:
                    durations.append((max(2, edge["duration"] - edge.get("discount", 0)), used + 1))
                for duration, next_used in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | node_masks[next_node]
                    next_state = (next_node, next_mask, next_used)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


